package com.jbrempresa.backend.controller;
import java.util.List;import org.springframework.core.io.Resource;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import com.jbrempresa.backend.core.context.ContextoOperacion;import com.jbrempresa.backend.entity.TipoArticulo;import com.jbrempresa.backend.repository.TipoArticuloRepository;import com.jbrempresa.backend.service.ImagenService;
@RestController@RequestMapping("/tipos-articulo")public class TipoArticuloController{private final TipoArticuloRepository repo;private final ContextoOperacion ctx;private final ImagenService imagenes;public TipoArticuloController(TipoArticuloRepository r,ContextoOperacion c,ImagenService i){repo=r;ctx=c;imagenes=i;}@GetMapping("/{clase}")public List<TipoArticulo> listar(@PathVariable String clase){return repo.findByEmpIdAndClaseAndActivoTrueOrderByNombre(ctx.empresaId(),clase(clase));}@PostMapping("/{clase}")public TipoArticulo guardar(@PathVariable String clase,@RequestBody TipoArticulo in){TipoArticulo t=in.getId()==null?new TipoArticulo():repo.findByEmpIdAndIdAndClase(ctx.empresaId(),in.getId(),clase(clase)).orElseThrow();t.setEmpId(ctx.empresaId());t.setClase(clase(clase));t.setNombre(in.getNombre().trim());t.setActivo(true);t.setUsuario(ctx.nombreUsuario());t.setFecha(ctx.fechaActual());return repo.save(t);}@DeleteMapping("/{clase}/{id}")public void eliminar(@PathVariable String clase,@PathVariable Long id){TipoArticulo t=repo.findByEmpIdAndIdAndClase(ctx.empresaId(),id,clase(clase)).orElseThrow();t.setActivo(false);t.setUsuario(ctx.nombreUsuario());t.setFecha(ctx.fechaActual());repo.save(t);}@PostMapping("/{clase}/{id}/imagen")public TipoArticulo imagen(@PathVariable String clase,@PathVariable Long id,@RequestParam MultipartFile archivo){TipoArticulo t=repo.findByEmpIdAndIdAndClase(ctx.empresaId(),id,clase(clase)).orElseThrow();t.setImagen(imagenes.guardar(ctx.empresaId(),"PRODUCTO".equals(clase(clase))?"PRODUCTOS":"SERVICIOS","tipos","tipo-"+id,archivo));t.setUsuario(ctx.nombreUsuario());t.setFecha(ctx.fechaActual());return repo.save(t);}@GetMapping("/{clase}/{id}/imagen")public ResponseEntity<Resource> verImagen(@PathVariable String clase,@PathVariable Long id){TipoArticulo t=repo.findByEmpIdAndIdAndClase(ctx.empresaId(),id,clase(clase)).orElseThrow();return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).body(imagenes.cargar(ctx.empresaId(),"PRODUCTO".equals(clase(clase))?"PRODUCTOS":"SERVICIOS","tipos",t.getImagen()));}private String clase(String c){String v=c.toUpperCase();if(!v.matches("PRODUCTO|SERVICIO"))throw new IllegalArgumentException("Clase no válida");return v;}}
